package com.vietanh.bilingualquiz;
import android.app.Activity; import android.content.Intent; import android.os.Bundle; import android.graphics.Color; import android.view.Gravity; import android.widget.*; import com.vietanh.bilingualquiz.ui.GradeSelectionActivity; import com.vietanh.bilingualquiz.ui.StatisticsActivity;
public class MainActivity extends Activity { @Override protected void onCreate(Bundle b){super.onCreate(b); LinearLayout root=new LinearLayout(this); root.setOrientation(LinearLayout.VERTICAL); root.setGravity(Gravity.CENTER); root.setPadding(48,64,48,64); TextView t=new TextView(this); t.setText("Bilingual Quiz\nÔn tập trắc nghiệm song ngữ"); t.setTextSize(24); t.setGravity(Gravity.CENTER); t.setTextColor(Color.rgb(20,60,120)); root.addView(t); addLevel(root,"Cấp tiểu học / Primary school",1,5); addLevel(root,"Cấp trung học cơ sở / Middle school",6,9); addLevel(root,"Cấp trung học phổ thông / High school",10,12); Button s=new Button(this); s.setText("Thống kê / Statistics"); s.setOnClickListener(v->startActivity(new Intent(this,StatisticsActivity.class))); root.addView(s); setContentView(root);} private void addLevel(LinearLayout root,String title,int first,int last){Button button=new Button(this); button.setText(title); button.setOnClickListener(v->{Intent i=new Intent(this,GradeSelectionActivity.class); i.putExtra("level",title); i.putExtra("firstGrade",first); i.putExtra("lastGrade",last); startActivity(i);}); root.addView(button);}}
